local function nS(p) return {vars={},decl={},parent=p} end
local function gV(sc,nm) local s=sc while s do if s.decl[nm] then return s.vars[nm] end s=s.parent end return _G[nm] end
local function sV(sc,nm,val) local s=sc while s do if s.decl[nm] then s.vars[nm]=val return end s=s.parent end _G[nm]=val end
local function dL(sc,nm,val) sc.vars[nm]=val sc.decl[nm]=true end
local eE,eM,eL,eS,eSt,mC,bT
function eE(n,sc) local op=n[1]
if op==1 then return K[n[2]+1]
elseif op==2 then return K[n[2]+1]
elseif op==3 then return true
elseif op==4 then return false
elseif op==5 then return nil
elseif op==6 then return gV(sc,K[n[2]+1])
elseif op==7 then local o=eE(n[2],sc) local k=eE(n[3],sc) return o[k]
elseif op==8 then local f=eE(n[2],sc) local a=eL(n[3],sc) return f(table.unpack(a))
elseif op==9 then local o=eE(n[2],sc) local nm=K[n[3]+1] local f=o[nm] local a=eL(n[4],sc) return f(o,table.unpack(a))
elseif op==10 then local oc=n[2]
if oc==14 then local l=eE(n[3],sc) if not l then return l end return eE(n[4],sc) end
if oc==15 then local l=eE(n[3],sc) if l then return l end return eE(n[4],sc) end
local a=eE(n[3],sc) local b=eE(n[4],sc)
if oc==1 then return a+b elseif oc==2 then return a-b elseif oc==3 then return a*b elseif oc==4 then return a/b
elseif oc==5 then return a%b elseif oc==6 then return a^b elseif oc==7 then return a..b elseif oc==8 then return a==b
elseif oc==9 then return a~=b elseif oc==10 then return a<b elseif oc==11 then return a<=b elseif oc==12 then return a>b
elseif oc==13 then return a>=b end
elseif op==11 then local a=eE(n[3],sc) local oc=n[2] if oc==1 then return -a elseif oc==2 then return not a else return #a end
elseif op==12 then return bT(n[2],sc)
elseif op==13 then return mC(n[2],n[3],sc)
end end
function eM(n,sc) local op=n[1]
if op==8 then local f=eE(n[2],sc) local a=eL(n[3],sc) return {f(table.unpack(a))}
elseif op==9 then local o=eE(n[2],sc) local nm=K[n[3]+1] local f=o[nm] local a=eL(n[4],sc) return {f(o,table.unpack(a))}
else return {eE(n,sc)} end end
function eL(list,sc) local out={} local cnt=#list
for i=1,cnt-1 do out[#out+1]=eE(list[i],sc) end
if cnt>0 then local last=eM(list[cnt],sc) for _,v in ipairs(last) do out[#out+1]=v end end
return out end
function bT(fields,sc) local t={} for _,f in ipairs(fields) do local ft=f[1]
if ft==0 then t[#t+1]=eE(f[3],sc)
elseif ft==1 then t[K[f[2]+1]]=eE(f[3],sc)
else t[eE(f[2],sc)]=eE(f[3],sc) end end return t end
function mC(params,body,defSc) return function(...) local args={...} local fsc=nS(defSc)
for i,pidx in ipairs(params) do dL(fsc,K[pidx+1],args[i]) end
local sig=eS(body,fsc) if sig and sig.ret then return table.unpack(sig.vals,1,sig.n) end end end
function eSt(s,sc) local op=s[1]
if op==20 then local vals=eL(s[3],sc) for i,nidx in ipairs(s[2]) do dL(sc,K[nidx+1],vals[i]) end return nil
elseif op==21 then local vals=eL(s[3],sc) for i,tn in ipairs(s[2]) do local to=tn[1]
if to==6 then sV(sc,K[tn[2]+1],vals[i]) elseif to==7 then local o=eE(tn[2],sc) local k=eE(tn[3],sc) o[k]=vals[i] end end return nil
elseif op==22 then for _,cl in ipairs(s[2]) do if eE(cl[1],sc) then return eS(cl[2],nS(sc)) end end
if s[3] then return eS(s[3],nS(sc)) end return nil
elseif op==23 then while eE(s[2],sc) do local sig=eS(s[3],nS(sc)) if sig then if sig.ret then return sig end if sig.brk then break end end end return nil
elseif op==31 then while true do local cs=nS(sc) local sig=eS(s[2],cs) local brk=false if sig then if sig.ret then return sig end if sig.brk then brk=true end end if brk then break end if eE(s[3],cs) then break end end return nil
elseif op==24 then local st=eE(s[3],sc) local sp=eE(s[4],sc) local stp=s[5] and eE(s[5],sc) or 1 local i=st
while (stp>0 and i<=sp) or (stp<0 and i>=sp) do local cs=nS(sc) dL(cs,K[s[2]+1],i)
local sig=eS(s[6],cs) if sig then if sig.ret then return sig end if sig.brk then break end end i=i+stp end return nil
elseif op==25 then local init=eL(s[3],sc) local f,st2,ctrl=init[1],init[2],init[3]
while true do local rets={f(st2,ctrl)} if rets[1]==nil then break end ctrl=rets[1] local cs=nS(sc)
for i,nidx in ipairs(s[2]) do dL(cs,K[nidx+1],rets[i]) end
local sig=eS(s[4],cs) if sig then if sig.ret then return sig end if sig.brk then break end end end return nil
elseif op==26 then dL(sc,K[s[2]+1],nil) local fn=mC(s[3],s[4],sc) sV(sc,K[s[2]+1],fn) return nil
elseif op==27 then local vals=eL(s[2],sc) return {ret=true,vals=vals,n=#vals}
elseif op==28 then return {brk=true}
elseif op==29 then return eS(s[2],nS(sc))
elseif op==30 then eE(s[2],sc) return nil
end end
function eS(list,sc) for _,s in ipairs(list) do local sig=eSt(s,sc) if sig then return sig end end return nil end
eS(B, nS(nil))
